
import type { DeliveryAddressAdvisoryResourceInput } from './DeliveryAddressAdvisoryResourceInput.js';
import type { DeliveryInputRequirementInput } from './DeliveryInputRequirementInput.js';

export type DeliveryPickupAvailabilityCandidateOutcomeInput = { "address_advisories"?: Array<DeliveryAddressAdvisoryResourceInput>; /** Why Flint could not calculate pickup availability and the action that can make calculation succeed. - `eligibility_context_invalid`: Create a new checkout session, then create a new quote. - `eligibility_dependency_failure`: Retry after the eligibility dependency recovers. - `pickup_method_unavailable`: Activate or choose an available pickup method. - `inventory_dependency_failure`: Retry after inventory availability and routing recover. */ "failure_category"?: "eligibility_context_invalid" | "eligibility_dependency_failure" | "pickup_method_unavailable" | "inventory_dependency_failure"; "input_requirements"?: Array<DeliveryInputRequirementInput>; "retryable"?: boolean; "type": "available" | "unavailable" | "input_required" | "cannot_calculate"; /** Why pickup is unavailable and the action that can make it eligible. - `eligibility_no_match`: Inspect eligibility_mismatches, then change the relevant buyer facts or method eligibility rule. - `inventory_insufficient`: Reduce the requested quantity, replenish inventory, or choose another pickup location. */ "unavailable_reason"?: "eligibility_no_match" | "inventory_insufficient"; };
